from collections.abc import Callable
import logging

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Call ``job`` exactly once and return ``"start:" + result + ":end"``.

    The helper uses no capabilities of its own: it does no I/O, prints
    nothing and logs nothing. Anything the job does with the caller's
    capabilities is the caller's business. Exceptions raised by ``job``
    propagate unchanged.
    """
    return "start:" + job() + ":end"


def test_wraps_result() -> None:
    assert wrapped(lambda: "x") == "start:x:end"


def test_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_result_containing_delimiters_is_not_altered() -> None:
    assert wrapped(lambda: "start:a:end") == "start:start:a:end:end"


def test_job_called_exactly_once() -> None:
    calls: list[int] = []

    def job() -> str:
        calls.append(1)
        return "r"

    assert wrapped(job) == "start:r:end"
    assert len(calls) == 1


def test_job_uses_caller_state() -> None:
    state = {"n": 41}

    def job() -> str:
        state["n"] += 1
        return str(state["n"])

    assert wrapped(job) == "start:42:end"
    assert state["n"] == 42


def test_exception_propagates() -> None:
    def job() -> str:
        raise ValueError("boom")

    with pytest.raises(ValueError, match="boom"):
        wrapped(job)


def test_helper_prints_nothing(capsys: pytest.CaptureFixture[str]) -> None:
    assert wrapped(lambda: "x") == "start:x:end"
    captured = capsys.readouterr()
    assert captured.out == ""
    assert captured.err == ""


def test_job_output_passes_through_untouched(
    capsys: pytest.CaptureFixture[str],
) -> None:
    def job() -> str:
        print("from job")
        return "x"

    assert wrapped(job) == "start:x:end"
    captured = capsys.readouterr()
    assert captured.out == "from job\n"
    assert captured.err == ""


def test_helper_logs_nothing(caplog: pytest.LogCaptureFixture) -> None:
    with caplog.at_level(logging.DEBUG):
        assert wrapped(lambda: "x") == "start:x:end"
    assert caplog.records == []


def test_job_logging_is_not_suppressed(caplog: pytest.LogCaptureFixture) -> None:
    logger = logging.getLogger("caller")

    def job() -> str:
        logger.warning("job message")
        return "x"

    with caplog.at_level(logging.DEBUG):
        assert wrapped(job) == "start:x:end"
    assert [r.getMessage() for r in caplog.records] == ["job message"]
